(() => {
  'use strict';
  const P=window.Portal,A=P?.prototypeUsers,O=P?.orderWorkspace;
  if(!A||!O||P.demoMode)return;
  const e=P.e, C=P.face2faceCommission;
  const internal=()=>A.internal()&&P.role==='internal';
  const fmt=n=>new Intl.NumberFormat('sv-SE',{maximumFractionDigits:1}).format(n);
  const money=n=>n===null?'Underlag saknas':fmt(n)+' kr';
  const today=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Stockholm'}).format(new Date());
  const valid=d=>C.validDate(d);
  const lost=new Set(['rejected','cannot_confirm','withdrawn','lost_before_start','lost_after_start']);
  const reasons={network:'Nätavtal saknas',address:'Felaktig adress',credit:'Kreditbedömning',other:'Annat'};
  const nav=[['overview','Översikt','home'],['partner-results','Försäljningsanalys','chart'],['partners','Partners','users'],['internal-orders','Ordrar','file'],['kickback','Provision & fakturaunderlag','money']];
  const f={mode:'year',value:today().slice(0,4),selectedMonths:[],partner:'all',channel:'all',category:'all'};
  let partnerTab='summary',orderSlice=null,query='',status='all',invoicePartner='vast';
  const metadata=()=>P.state.internalSales||{models:[],costs:[],reviews:{},partners:{}};
  const all=()=>internal()?O.allOrders():[];
  const name=id=>P.getPartner(id)?.name||id;
  const channel=r=>r.channel||((r.examplePack==='flow2026'||/^order-demo-(vast|syd)-\d+$/.test(r.id))?({vast:'Fältförsäljning',syd:'Telefonförsäljning'}[r.partner]||'Ej angiven'):'Ej angiven');
  const entryDate=r=>valid(r.createdAt)?r.createdAt:valid(r.registeredAt)?r.registeredAt:'';
  function eventDate(r,key){const field={confirmed:'confirmedAt',approved:'approvedAt',registered:'registeredAt'}[key];return [field?r[field]:'',...O.historyFor(r).filter(h=>h.status===key).map(h=>h.at.slice(0,10))].filter(valid).sort()[0]||'';}
  const monthName=m=>new Intl.DateTimeFormat('sv-SE',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(m+'-01T12:00:00Z'));
  const selectedMonths=()=>f.selectedMonths.length?[...new Set(f.selectedMonths)].sort():[f.value];
  const periodLabel=()=>f.mode==='year'?f.value:selectedMonths().map(monthName).join(', ');
  const inPeriod=d=>valid(d)&&(f.mode==='year'?d.startsWith(f.value):selectedMonths().includes(d.slice(0,7)));
  function periodControls(){const year=f.value.slice(0,4);return `<label>Period<select data-is-filter="mode">${options([['month','Månad'],['year','År']],f.mode)}</select></label><label>År<input data-is-filter="value" type="number" min="2000" max="2100" value="${e(year)}" required></label>${f.mode==='month'?`<div class="is-month-field"><span id="is-month-label">Månader</span><details class="is-month-picker"><summary aria-labelledby="is-month-label is-month-selection"><span id="is-month-selection">${e(selectedMonths().map(m=>monthName(m).replace(' '+year,'')).join(', '))}</span></summary><fieldset><legend>Välj en eller flera månader</legend>${Array.from({length:12},(_,i)=>{const m=year+'-'+String(i+1).padStart(2,'0');return `<label><input type="checkbox" aria-label="${e(monthName(m))}" data-is-month="${m}" ${selectedMonths().includes(m)?'checked':''}>${e(monthName(m).replace(' '+year,''))}</label>`;}).join('')}</fieldset></details></div>`:''}`;}

  const matches=r=>(f.partner==='all'||r.partner===f.partner)&&(f.channel==='all'||channel(r)===f.channel)&&(f.category==='all'||r.category===f.category);
  const filtered=()=>all().filter(matches);
  const cohort=()=>filtered().filter(r=>r.status!=='draft'&&inPeriod(entryDate(r)));
  const eventRows=key=>filtered().filter(r=>inPeriod(eventDate(r,key)));
  const options=(rows,value)=>rows.map(([id,label])=>`<option value="${e(id)}" ${id===value?'selected':''}>${e(label)}</option>`).join('');
  const button=(label,attr,cls='btn btn-secondary')=>`<button type="button" class="${cls}" ${attr}>${label}</button>`;
  const heading=(title,description)=>`<div class="is-page"><div class="page-head"><div><span class="eyebrow">KRAFTRINGEN / PARTNERFÖRSÄLJNING</span><h1>${title}</h1><p>${description}</p></div></div>`;
  function filters(){return `<section class="card is-filters" aria-label="Gemensamt analysurval">${periodControls()}<label>Partner<select data-is-filter="partner">${options([['all','Alla partners'],...P.partnerRegistry.map(p=>[p.id,p.name])],f.partner)}</select></label><label>Kanal<select data-is-filter="channel">${options([['all','Alla kanaler'],...[...new Set(all().map(channel))].sort().map(c=>[c,c])],f.channel)}</select></label><label>Kundsegment<select data-is-filter="category">${options([['all','Alla segment'],['consumer','Konsument'],['business','Företag']],f.category)}</select></label></section>`;}
  function coverage(){const ids=new Set(all().map(r=>r.partner));return `<p class="is-note">Fiktivt orderunderlag från ${ids.size} av ${P.partnerRegistry.length} partners. Övriga partners har inget orderunderlag i denna analys. Historiska rapportexempel summeras inte in. Kanal för de befintliga exempelpaketen är ett demoantagande: Face2face = fält, Savera = telefon. Övriga ordrar utan kanal visas som Ej angiven.</p>`;}
  function kpis(){const group=cohort(),binding=eventRows('confirmed'),active=eventRows('active'),fail=group.filter(r=>lost.has(r.status));return `<div class="is-kpis">${[['Inkomna ordrar',group.length,'Skapade i perioden, utkast undantagna'],['Nya bindande avtal',binding.length,'Första sparade bindandedatum i perioden'],['Leveransstarter',active.length,'Sparad aktiv-händelse i perioden'],['Bortfall i ordergruppen',group.length?fmt(fail.length/group.length*100)+' %':'—',fail.length+' av '+group.length+' ordrar, hittills']].map(([label,value,note])=>`<article class="card"><span>${label}</span><strong>${value}</strong><small>${note}</small></article>`).join('')}</div>`;}
  function flow(){const rows=cohort(),s=O.flowSummary(rows),max=Math.max(1,rows.length);return `<section class="card is-panel"><div class="is-section-head"><div><span class="eyebrow">ORDERGRUPPENS UTVECKLING</span><h2>Från order till aktivt avtal</h2><p class="is-period-label"><strong>Period: ${e(periodLabel())}</strong></p></div>${button('Visa ordergruppen','data-is-slice="cohort"')}</div><p>Ordrar inkomna under vald period. Visar hur långt samma ordrar har nått hittills, även efter vald period. Klicka på en stapel, ett vänteläge eller ett bortfall.</p><div class="is-waterfall">${s.stages.map((v,i)=>`<div class="is-flow-step"><button class="is-flow-bar" data-is-stage="${v.key}" aria-label="${e(O.statuses[v.key])}: ${v.entered} ordrar"><strong>${v.entered}</strong><span class="is-flow-track"><span style="height:${v.entered/max*100}%;min-height:${v.entered?4:0}px"></span></span><b>${i+1}. ${e(O.statuses[v.key])}</b></button><button class="text-button" data-is-wait="${v.key}">${i===4?'Aktiva nu':'Kvar här'}: ${v.remaining}</button><button class="text-button is-loss" data-is-loss-stage="${v.key}">Bortfall: ${v.lost}</button></div>`).join('')}</div><div class="is-flow-foot">${button('Väntar före registrering: '+s.sent,'data-is-slice="sent"')}${button('Okänd fas: '+s.unknown.length,'data-is-slice="unknown"')}</div><p class="is-note">Bortfall efter start visas vid Aktivt avtal. Väntande ordrar är inte bortfall. Okänd fas redovisas separat. ${filtered().filter(r=>r.status!=='draft'&&!entryDate(r)).length} ordrar saknar inkomstdatum och kan inte placeras i en period.</p></section>`;}
  const groupCounts=(rows,key)=>Object.entries(rows.reduce((m,r)=>{const k=key(r);m[k]=(m[k]||0)+1;return m;},{})).sort((a,b)=>b[1]-a[1]);
  function bars(title,rows,note){const max=Math.max(1,...rows.map(r=>r[1]));return `<section class="card is-panel"><h2>${title}</h2><p>${note}</p>${rows.length?`<div class="is-bars">${rows.map(([label,n])=>`<div><span>${e(label)}</span><div class="is-bar-track"><i style="width:${n/max*100}%"></i></div><strong>${fmt(n)}</strong></div>`).join('')}</div>`:'<p>Inga registrerade händelser i urvalet.</p>'}</section>`;}
  function trend(){const rows=filtered(),months=Array.from({length:12},(_,i)=>f.value.slice(0,4)+'-'+String(i+1).padStart(2,'0'));return bars('Bindande avtal över året',months.map(m=>[m,rows.filter(r=>eventDate(r,'confirmed').startsWith(m)).length]),'Första bindandedatum per order. Hela '+f.value.slice(0,4)+' visas som jämförelse, med samma partner-, kanal- och segmenturval.');}
  function attention(){const rows=all().filter(r=>['sent','needs_completion','registered'].includes(r.status));return `<section class="card is-panel"><div class="is-section-head"><h2>Att följa upp</h2>${button('Öppna arbetslistan','data-is-attention')}</div><p>${rows.length} ordrar väntar på registrering, granskning eller komplettering. Arbetslistan omfattar alla perioder och partners.</p><p>${all().filter(r=>lost.has(r.status)&&lossReason(r)==='Ej angiven').length} bortfall saknar angiven orsak.</p></section>`;}
  function overview(){return heading('Översikt','Partnerförsäljningen i korthet. Fördjupa urvalet i Försäljningsanalys.')+filters()+coverage()+kpis()+flow()+`<div class="is-columns">${trend()}${bars('Nya bindande avtal per kanal',groupCounts(eventRows('confirmed'),channel),'Periodens bindande avtal, uppdelade efter försäljningskanal.')}</div>`+attention()+'</div>';}
  function lossReason(r){const record=O.historyFor(r).filter(h=>lost.has(h.status)).at(-1);return metadata().lossReasons?.[r.id]?.reason||reasons[record?.reason]||r.cancellationReason||r.lossReason||'Ej angiven';}
  function costs(rows){
    // A cost record explicitly allocates ALL acquisition costs to a partner's incoming-order month.
    // Subsets cannot inherit the full partner cost and therefore never show a misleading CAC.
    const keysInRows=new Set(rows.map(r=>r.partner+'|'+entryDate(r).slice(0,7)));
    const full=all().filter(r=>r.status!=='draft'&&keysInRows.has(r.partner+'|'+entryDate(r).slice(0,7)));
    if(full.length!==rows.length)return {complete:false,total:null,commission:null,reason:'Urvalet innehåller bara en del av en partner/månad. Kostnaden kan inte fördelas säkert på detta urval.'};
    const keys=[...new Set(rows.map(r=>r.partner+'|'+entryDate(r).slice(0,7)))];
    const records=keys.map(key=>metadata().costs?.find(c=>c.partner+'|'+c.month===key));
    const complete=keys.length>0&&records.every(c=>c&&['commission','leads','campaign','other'].every(k=>Number.isFinite(c[k])&&c[k]>=0));
    return {complete,total:complete?records.reduce((s,c)=>s+c.commission+c.leads+c.campaign+c.other,0):null,commission:complete?records.reduce((s,c)=>s+c.commission,0):null,reason:complete?'Allokerade kostnader för samma ordergrupp. Belopp exkl. moms.':`${records.filter(Boolean).length} av ${keys.length} partner/månader har kostnadsunderlag. Inget antas vara gratis.`};
  }
  function costPanel(rows=cohort()){const c=costs(rows),bound=rows.filter(r=>O.reached(r,'confirmed')).length,active=rows.filter(r=>O.reached(r,'active')).length;return `<section class="card is-panel"><h2>Anskaffningskostnad för ordergruppen</h2><p>${e(c.reason)}</p>${metadata().costs?.some(v=>v.demo)?'<p class="is-note">Inlästa demokostnader är illustrativa och ska inte jämställas med fakturaunderlagets provisionsberäkning.</p>':''}<dl class="is-metrics"><div><dt>Total allokerad kostnad</dt><dd>${money(c.total)}</dd></div><div><dt>CAC per bindande avtal</dt><dd>${c.complete&&bound?money(c.total/bound):'—'}</dd></div><div><dt>CAC per startat avtal</dt><dd>${c.complete&&active?money(c.total/active):'—'}</dd></div><div><dt>Partnerersättning per bindande avtal</dt><dd>${c.complete&&bound?money(c.commission/bound):'—'}</dd></div></dl><p class="is-note">Nämnare: ${bound} avtal har blivit bindande, ${active} har startat. Senare bortfall behåller sin uppnådda händelse. Förskott och avräkning ska ingå en gång i kostnadsunderlaget. Detta är en lokalt inmatad demokalkyl, inte bokföringsdata.</p>${A.admin()?button('Lägg in kostnadsunderlag','data-is-cost'):''}</section>`;}
  function comparison(){return `<section class="card is-panel"><h2>Kanaler – volym och konvertering</h2><div class="table-wrap"><table><thead><tr><th>Kanal</th><th>Inkomna ordrar</th><th>Blivit bindande</th><th>Bortfall</th><th>Konvertering</th><th>CAC / bindande</th></tr></thead><tbody>${[...new Set(cohort().map(channel))].map(c=>{const rows=cohort().filter(r=>channel(r)===c),n=rows.filter(r=>O.reached(r,'confirmed')).length;return `<tr><td>${e(c)}</td><td>${rows.length}</td><td>${n}</td><td>${rows.filter(r=>lost.has(r.status)).length}</td><td>${fmt(n/rows.length*100)} %</td><td>${costs(rows).complete&&n?money(costs(rows).total/n):'Underlag saknas'}</td></tr>`;}).join('')||'<tr><td colspan="5">Inga ordrar i perioden.</td></tr>'}</tbody></table></div><p class="is-note">Samma ordergrupp följs genom processen. CAC visas när kostnadsunderlaget täcker kanalens hela ordergrupp. Delade partner/månader kräver ytterligare kostnadsfördelning.</p></section>`;}
  function leadTime(){const ds=cohort().map(r=>{const start=entryDate(r),end=eventDate(r,'confirmed');return valid(start)&&valid(end)&&end>=start?(Date.parse(end)-Date.parse(start))/86400000:null;}).filter(n=>n!==null).sort((a,b)=>a-b),median=ds.length?(ds[Math.floor((ds.length-1)/2)]+ds[Math.floor(ds.length/2)])/2:null;return `<section class="card is-panel"><h2>Tid till bindande avtal</h2><strong class="is-big">${median===null?'—':fmt(median)+' dagar'}</strong><p>Median från inkomstdatum till första bindandedatum. ${ds.length} ordrar har användbara datum; övriga ingår inte i beräkningen.</p></section>`;}
  function analysis(){return heading('Försäljningsanalys','Förstå volymer, konvertering, bortfall och kostnader ur Kraftringens perspektiv.')+filters()+coverage()+`<div class="is-columns">${bars('Bindande avtal per produkt',groupCounts(eventRows('confirmed'),r=>r.product||'Ej angiven'),'Periodens nya bindande avtal.')}${bars('Bindande avtal per avtalstyp',groupCounts(eventRows('confirmed'),r=>r.termType==='fixed'||Number(r.termMonths)>0?'Fast avtalstid':'Löpande avtal'),'Orderns sparade avtalstid.')}</div>`+comparison()+`<div class="is-columns">${bars('Bortfallsorsaker',groupCounts(cohort().filter(r=>lost.has(r.status)),lossReason),'Samtliga bortfall hittills i den valda ordergruppen. Ej angiven är en datalucka.')}${bars('Bortfall per steg',groupCounts(cohort().filter(r=>lost.has(r.status)),r=>O.flowPosition(r)===null?'Okänd fas':O.statuses[['registered','approved','confirmation_sent','confirmed','active'][O.flowPosition(r)]]||'Före registrering'),'Det sista uppnådda steget före bortfallet.')}</div>`+costPanel()+leadTime()+`<section class="card is-panel"><h2>Exempelunderlag för analys</h2><p>Vill du prova kostnader och olika bortfallsorsaker? Lägg till uttryckligen fiktiva kompletteringar för de befintliga exempelordrarna. Befintliga kostnader och klassificeringar behålls.</p>${A.admin()?button('Ladda fiktivt analysunderlag','data-is-examples'):''}${button('Visa samlat orderflöde','data-go="overview"')}</section>`+'</div>';}
  function orderTable(rows){return `<div class="table-wrap"><table><thead><tr><th>Order</th><th>Partner / kanal</th><th>Produkt</th><th>Inkommen</th><th>Status</th><th>Orsak</th></tr></thead><tbody>${rows.map(r=>`<tr><td><button class="text-button" data-is-order="${e(r.id)}">${e(r.id)}</button></td><td>${e(name(r.partner))}<small class="ow-id">${e(channel(r))}</small></td><td>${e(r.product)}</td><td>${e(entryDate(r)||'Datum saknas')}</td><td>${e(O.statuses[r.status]||r.status)}</td><td>${lost.has(r.status)?e(lossReason(r)):'—'}</td></tr>`).join('')||'<tr><td colspan="6">Inga ordrar matchar urvalet.</td></tr>'}</tbody></table></div>`;}
  function ordersPage(){const base=orderSlice?all().filter(r=>orderSlice.ids.includes(r.id)):cohort(),rows=base.filter(r=>(status==='all'||r.status===status)&&(!query||[r.id,r.product,name(r.partner)].join(' ').toLocaleLowerCase('sv').includes(query.toLocaleLowerCase('sv'))));return heading('Ordrar','Kraftringens arbetslista för alla partners. Öppna en order för historik och handläggning.')+filters()+`<section class="card is-panel">${orderSlice?`<p class="is-selection">${e(orderSlice.label)} · ${base.length} ordrar ${button('Rensa detaljurval','data-is-clear')}</p>`:'<p>Inkomna i vald period, utkast undantagna. Detaljurval från diagram behåller exakt den klickade gruppen.</p>'}<div class="is-filters"><label>Sök order, produkt eller partner<input type="search" data-is-query value="${e(query)}"></label><label>Status<select data-is-status>${options([['all','Alla statusar'],...Object.entries(O.statuses)],status)}</select></label>${button('Alla ordrar, även utkast','data-is-all-orders')}</div><p>${rows.length} ordrar</p>${orderTable(rows)}</section></div>`;}
  function partnerList(){return heading('Partners','Jämför samarbeten och öppna partnerns arbetsrum för uppföljning och inställningar.')+filters()+`<section class="card is-panel"><div class="is-section-head"><h2>Partnersamarbeten</h2>${A.admin()?button('Ny partner','data-pu-partner'):''}</div><div class="table-wrap"><table><thead><tr><th>Partner</th><th>Typ</th><th>Inkomna ordrar</th><th>Bindande i perioden</th><th>Ansvarig</th><th></th></tr></thead><tbody>${P.partnerRegistry.filter(p=>f.partner==='all'||p.id===f.partner).map(p=>{const known=all().some(r=>r.partner===p.id);return `<tr><td><strong>${e(p.name)}</strong></td><td>${e(p.typeLabel||p.type)}</td><td>${known?cohort().filter(r=>r.partner===p.id).length:'—'}</td><td>${known?eventRows('confirmed').filter(r=>r.partner===p.id).length:'—'}</td><td>${e(metadata().partners?.[p.id]?.owner||'Ej utsedd')}</td><td>${button('Öppna samarbete',`data-is-partner="${e(p.id)}"`)}</td></tr>`;}).join('')}</tbody></table></div></section>`+coverage()+'</div>';}
  const selected=()=>P.getPartner(P.selectedPartnerId)?P.selectedPartnerId:P.partnerRegistry[0]?.id;
  function partnerHub(){const id=selected(),p=P.getPartner(id),rows=all().filter(r=>r.partner===id),m=metadata().partners?.[id]||{};return heading(e(p.name),'Partnerns resultat, villkor och administration på ett ställe.')+button('← Alla partners','data-go="partners"','text-button')+`<nav class="is-tabs" aria-label="Partnersamarbetets delar">${[['summary','Sammanfattning'],['settings','Samarbete & produkter'],['models','Provision & villkor'],['users','Användare'],['invoices','Fakturaunderlag']].map(([key,label])=>button(label,`data-is-tab="${key}" aria-current="${partnerTab===key?'page':'false'}"`)).join('')}</nav>`+(partnerTab==='summary'?`<section class="card is-panel"><h2>Samarbetet i korthet</h2><p>${e(m.description||'Beskrivning av samarbetet är inte inlagd ännu.')}</p><p>Intern ansvarig: <strong>${e(m.owner||'Ej utsedd')}</strong></p><div class="is-kpis">${[['Inkomna '+periodLabel(),rows.filter(r=>r.status!=='draft'&&inPeriod(entryDate(r))).length],['Bindande '+periodLabel(),rows.filter(r=>inPeriod(eventDate(r,'confirmed'))).length],['Aktiva nu',rows.filter(r=>r.status==='active').length],['Bortfall totalt',rows.filter(r=>lost.has(r.status)).length]].map(([label,n])=>`<article><span>${e(label)}</span><strong>${rows.length?n:'—'}</strong></article>`).join('')}</div><p>${rows.length?rows.length+' lokala exempelordrar.':'Orderunderlag saknas.'} ${A.users().filter(u=>u.partner===id&&u.active).length} aktiva partneranvändare.</p>${button('Analysera partnerns försäljning',`data-is-analyse="${e(id)}"`)} ${button('Partnerresa & uppföljning','data-go="journey"')}</section>`:partnerTab==='settings'?`<section class="card is-panel"><h2>Samarbete & produkter</h2><p>${e(m.description||'Beskrivning saknas.')}</p><p>Typ: ${e(p.typeLabel||p.type)} · CRM: ${p.crmMode==='portal'?'Partnerportalen':'Eget CRM'}</p>${A.admin()?button('Beskriv samarbete & ansvar','data-is-profile')+' '+button('Ändra partnerprofil',`data-is-edit-profile="${e(id)}"`)+' '+button('Sortiment & prislistor','data-go="product-access"'):'<p>Administratören kan ändra samarbete och sortiment.</p>'}${p.type==='property'?button('Fastighetssamarbetet','data-go="property-partnership"'):''}${p.type==='employee'?button('Personalavtalet','data-go="employee-channel"'):''}</section>`:partnerTab==='models'?modelPanel(id):partnerTab==='users'?usersPanel(id):`<div class="is-filters">${periodControls()}</div>`+financePanel(id))+ '</div>';}
  function usersPanel(id){const users=A.users().filter(u=>u.partner===id);return `<section class="card is-panel"><div class="is-section-head"><h2>Partnerns användare</h2>${A.admin()?button('Lägg till användare',`data-is-new-user="${e(id)}"`):''}</div><p>Inaktivera konton som ska tas bort från åtkomsten. Ordrar och ändringshistorik bevaras.</p><div class="table-wrap"><table><thead><tr><th>Namn</th><th>Roll</th><th>Status</th><th></th></tr></thead><tbody>${users.map(u=>`<tr><td>${e(u.name)}<small class="ow-id">${e(u.email)}</small></td><td>${e(A.roles[u.role])}</td><td>${u.active?'Aktiv':'Inaktiv'}</td><td>${A.admin()?button('Redigera / inaktivera',`data-pu-edit="${e(u.id)}"`):''}</td></tr>`).join('')||'<tr><td colspan="4">Inga partneranvändare.</td></tr>'}</tbody></table></div></section>`;}
  function modelPanel(id){const models=(metadata().models||[]).filter(m=>m.partner===id).sort((a,b)=>b.from.localeCompare(a.from));return `<section class="card is-panel"><h2>Provision & villkor</h2>${id==='vast'?'<p><strong>Befintlig beräkningsmodell:</strong> 1 500 kr per bindande avtal, 80 % förskott på godkända. Förskott avräknas mot samma godkännandemånad. Fakturaunderlaget använder denna modell.</p>':'<p>Ingen verifierad automatisk provisionsmodell är ansluten för denna partner.</p>'}<p>Dokumentera nya versioner med giltighetsdatum. Versionerna nedan är förslag och ändrar inte befintliga beräkningar eller tidigare fakturaunderlag.</p>${A.admin()?button('Ny modellversion · förslag','data-is-model'):''}${models.map(m=>`<details class="is-model"><summary>${e(m.from)} · ${e(m.title)} · Förslag</summary><p>${e(m.description)}</p><p>Skapad ${e(m.at)} · ${e(A.users().find(u=>u.id===m.actor)?.name||m.actor)}</p></details>`).join('')||'<p>Inga nya modellförslag sparade.</p>'}</section>`;}
  function months(){return f.mode==='month'?selectedMonths():Array.from({length:12},(_,i)=>f.value+'-'+String(i+1).padStart(2,'0'));}
  function invoiceRows(id){return months().map(month=>{const calc=id==='vast'?C.calculate(all().filter(r=>r.partner===id),month):null,key=id+'|'+month,review=metadata().reviews?.[key];return {month,calc,key,review};});}
  function financePanel(id){return `<section class="card is-panel"><h2>Fakturaunderlag · ${e(name(id))}</h2><p>Beräkning per utfallsmånad, med avräkning mot godkännandemånad. Kanal- och segmentfilter påverkar inte partnerns avräkning. Inga fakturor eller betalningar skickas här.</p><div class="table-wrap"><table><thead><tr><th>Månad</th><th>Förskott</th><th>Extra avräkning</th><th>Beräknad ersättning</th><th>Granskning · demo</th><th></th></tr></thead><tbody>${invoiceRows(id).map(({month,calc,key,review})=>{const ok=calc&&!calc.missing.length;return `<tr><td>${e(month)}</td><td>${ok?money(calc.advance):'—'}</td><td>${ok?money(calc.extra):'—'}</td><td>${ok?money(calc.amount):'Underlag saknas'}</td><td>${e(review?.status||'Preliminär')}</td><td>${button('Granska',`data-is-review="${e(key)}"`)}</td></tr>`;}).join('')}</tbody></table></div>${id==='vast'?`<p>Äldre ordrar med saknade händelsedatum blockerar totalsumman. Det befintliga detaljunderlaget erbjuder ett uttryckligt val av det kompletta exempelpaketet.</p>${button('Öppna avräkning & Excel-export',`data-is-finance-detail="${e(id)}"`)}`:'<p>Komplettera och verifiera en beräkningsmodell innan ersättning kan räknas fram.</p>'}</section>`;}
  function finance(){return heading('Provision & fakturaunderlag','Granska ersättningar och underlag. Försäljningsdiagrammen finns i Försäljningsanalys.')+filters()+`<section class="card is-panel"><label class="ow-field">Partner för fakturaunderlag<select data-is-invoice-partner>${options(P.partnerRegistry.filter(p=>f.partner==='all'||p.id===f.partner).map(p=>[p.id,p.name]),f.partner==='all'?invoicePartner:f.partner)}</select></label><p>Granskningsstatus är lokal demo och innebär inte att en faktura skickats eller betalats.</p></section>`+financePanel(f.partner==='all'?invoicePartner:f.partner)+(oldRoutes.kickback?`<details class="card is-panel"><summary>Äldre ekonomiskt underlag</summary><p>Separata historiska exempel från tidigare ekonomivy. De ingår inte i den nya orderanalysen.</p>${button('Öppna äldre underlag','data-go="internal-legacy-finance"')}</details>`:'')+'</div>';}
  function commit(change){if(!internal()||!A.admin())return false;const before=P.state.internalSales,next=JSON.parse(JSON.stringify(metadata()));change(next);P.state.internalSales=next;if(!P.save()){if(before===undefined)delete P.state.internalSales;else P.state.internalSales=before;return false;}return true;}
  const field=(key,label,value='',type='text')=>`<label class="ow-field">${label}<input name="${key}" type="${type}" value="${e(String(value))}" required ${type==='number'?'min="0" step="0.01"':'maxlength="250"'}></label>`;
  function editDialog(title,html,save){if(!internal()||!A.admin())return;P.openDialog(title,`<form id="is-form" class="ow-form">${html}<p role="alert" tabindex="-1"></p><button class="btn btn-primary">Spara lokalt</button></form>`,()=>{const form=document.querySelector('#is-form');form.onsubmit=ev=>{ev.preventDefault();const result=save(Object.fromEntries(new FormData(form)));if(result!==true){const alert=form.querySelector('[role="alert"]');alert.textContent=typeof result==='string'?result:'Kunde inte spara. Tidigare uppgifter är kvar.';alert.focus();return;}P.closeDialog();P.render();P.toast('Sparat lokalt i demon.');};});}
  function editCost(){const id=f.partner==='all'?selected():f.partner,month=f.mode==='month'?selectedMonths()[0]:f.value+'-01';editDialog('Allokera anskaffningskostnader',`<p>Fördela samtliga kostnader på partnerns ordrar inkomna under månaden. Ange 0 endast när kostnaden är känd och faktiskt noll. Förskott och avräkning får inte dubbelräknas. Belopp exkl. moms.</p><label class="ow-field">Partner<select name="partner">${options(P.partnerRegistry.map(p=>[p.id,p.name]),id)}</select></label>${field('month','Ordergruppens inkomstmånad',month,'month')}${field('commission','Total partnerersättning, kr','','number')}${field('leads','Köpta leads, kr','','number')}${field('campaign','Kampanjer, kr','','number')}${field('other','Övriga anskaffningskostnader, kr','','number')}${field('note','Källa / allokeringsförklaring')}`,d=>{if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(d.month)||!P.getPartner(d.partner)||['commission','leads','campaign','other'].some(k=>!d[k]||!Number.isFinite(Number(d[k]))||Number(d[k])<0)||!d.note.trim())return 'Kontrollera månad, partner och samtliga kostnader.';const value={...d,...Object.fromEntries(['commission','leads','campaign','other'].map(k=>[k,Number(d[k])])),at:new Date().toISOString(),actor:A.current().id};return commit(m=>{const old=m.costs.find(c=>c.partner===d.partner&&c.month===d.month);m.costHistory=[...(m.costHistory||[]),{before:old||null,after:value}];m.costs=m.costs.filter(c=>c.partner!==d.partner||c.month!==d.month).concat(value);});});}
  function setSlice(label,rows){orderSlice={label,ids:rows.map(r=>r.id)};query='';status='all';P.go('internal-orders');}
  function openOrder(id){const r=all().find(r=>r.id===id);if(!r)return;P.openDialog('Order '+r.id,`<p><strong>${e(name(r.partner))}</strong> · ${e(r.product)} · ${e(O.statuses[r.status])}</p><h3>Statushistorik</h3><ol>${O.historyFor(r).map(h=>`<li>${e(h.at.slice(0,10))} · ${e(O.statuses[h.status]||h.status)}${h.reason?' · '+e(reasons[h.reason]||h.reason):''}</li>`).join('')||'<li>Daterad historik saknas.</li>'}</ol><p>Dokument, godkännanden, återsändning och statusändringar finns i den befintliga handläggningsvyn.</p>${button('Öppna handläggningsvyn',`data-is-handle="${e(r.id)}"`)}${button('Visa alla partnerns ordrar',`data-is-partner-orders="${e(r.partner)}"`)}${lost.has(r.status)&&A.admin()?button('Klassificera bortfallsorsak',`data-is-classify="${e(r.id)}"`):''}`);}
  function bind(){document.querySelectorAll('[data-is-month]').forEach(el=>el.onchange=()=>{const m=el.dataset.isMonth,chosen=selectedMonths();if(!el.checked&&chosen.length===1){el.checked=true;P.toast('Välj minst en månad.');return;}f.selectedMonths=el.checked?[...new Set([...chosen,m])].sort():chosen.filter(v=>v!==m);f.value=f.selectedMonths[0];orderSlice=null;P.render();const picker=document.querySelector('.is-month-picker');if(picker)picker.open=true;document.querySelector(`[data-is-month="${m}"]`)?.focus();});document.querySelectorAll('[data-is-filter]').forEach(el=>el.onchange=()=>{const k=el.dataset.isFilter;if(k==='mode'){f.mode=el.value;f.value=f.mode==='year'?f.value.slice(0,4):(f.selectedMonths[0]||f.value.slice(0,4)+'-01');}else if(k==='value'){if(!/^(20\d{2}|2100)$/.test(el.value))return;f.selectedMonths=selectedMonths().filter(m=>m.length===7).map(m=>el.value+m.slice(4));f.value=f.mode==='year'?el.value:(f.selectedMonths[0]||el.value+'-01');}else f[k]=el.value;orderSlice=null;P.render();document.querySelector(`[data-is-filter="${k}"]`)?.focus();});const q=document.querySelector('[data-is-query]');if(q)q.oninput=()=>{query=q.value;P.render();const el=document.querySelector('[data-is-query]');el.focus();};const s=document.querySelector('[data-is-status]');if(s)s.onchange=()=>{status=s.value;P.render();};const ip=document.querySelector('[data-is-invoice-partner]');if(ip)ip.onchange=()=>{invoicePartner=ip.value;P.render();};}
  const oldRoutes={};for(const [id,render] of [['internal-overview',overview],['partner-results',analysis],['partners',partnerList],['partner-detail',partnerHub],['kickback',finance],['internal-orders',ordersPage]]){oldRoutes[id]=P.routes[id];P.register(id,{render:()=>internal()?render():oldRoutes[id]?.render?.()||'',bind:()=>internal()?bind():oldRoutes[id]?.bind?.()});}
  P.register('internal-legacy-finance',{render:()=>internal()?oldRoutes.kickback?.render?.()||'':'',bind:()=>{if(internal())oldRoutes.kickback?.bind?.();}});
  const previous=P.render;P.render=()=>{previous();if(!internal())return;const active=['partner-detail','journey','product-access','employee-channel','property-partnership'].includes(P.page)?'partners':P.page;document.querySelector('#nav').innerHTML=[...nav,['academy','Utbildning','book'],['movein-cases','Inflyttningsärenden','home'],['customer-cases','Kundärenden','file'],...(A.admin()?[['user-admin','Användare & roller','users']]:[])].map(([id,label,ic])=>`<button class="nav-button ${active===id?'active':''}" data-go="${id}" aria-current="${active===id?'page':'false'}">${P.icon(ic)}<span>${label}</span></button>`).join('');if(['partner-detail',...nav.map(n=>n[0])].includes(P.page))document.querySelectorAll('.ow-tabs').forEach(n=>n.remove());document.querySelector('#current-page').textContent=nav.find(n=>n[0]===P.page)?.[1]||(P.page==='partner-detail'?name(selected()):document.querySelector('#current-page').textContent);};
  document.addEventListener('click',ev=>{const b=ev.target.closest('button');if(!b||!internal())return;const d=b.dataset;
    if(d.isStage)setSlice('Har nått '+O.statuses[d.isStage],cohort().filter(r=>O.reached(r,d.isStage)));
    if(d.isWait)setSlice('Kvar: '+O.statuses[d.isWait],cohort().filter(r=>O.matchesFlow(r,'flow:remaining:'+d.isWait)));
    if(d.isLossStage)setSlice('Bortfall efter '+O.statuses[d.isLossStage],cohort().filter(r=>lost.has(r.status)&&O.flowPosition(r)===['registered','approved','confirmation_sent','confirmed','active'].indexOf(d.isLossStage)));
    if(d.isSlice)setSlice(d.isSlice==='cohort'?'Vald ordergrupp':d.isSlice==='sent'?'Väntar före registrering':'Okänd fas',cohort().filter(r=>d.isSlice==='cohort'||(d.isSlice==='sent'?r.status==='sent':O.flowPosition(r)===null)));
    if('isAttention'in d)setSlice('Att följa upp · alla perioder',all().filter(r=>['sent','registered','needs_completion'].includes(r.status)));
    if('isAllOrders'in d)setSlice('Alla ordrar · alla perioder och partners',all());
    if('isClear'in d){orderSlice=null;P.render();}
    if(d.isOrder)openOrder(d.isOrder);
    if(d.isClassify){const row=all().find(r=>r.id===d.isClassify);if(row&&lost.has(row.status))editDialog('Klassificera bortfallsorsak',`<p>En separat analysklassificering. Orderns sparade historik ändras inte.</p><label class="ow-field">Orsak<select name="reason">${options(['Kunden avstår','Ånger','Kreditbedömning','Felaktiga uppgifter','Dubblett','Uteblivet kundgodkännande','Nätavtal saknas','Annat'].map(v=>[v,v]),lossReason(row))}</select></label>${field('note','Motivering')}`,value=>commit(m=>{const before=m.lossReasons?.[row.id];m.lossReasons={...m.lossReasons,[row.id]:{...value,at:new Date().toISOString(),actor:A.current().id,history:[...(before?.history||[]),...(before?[before.reason]:[])]}};}));}

    if(d.isPartnerOrders){P.closeDialog();setSlice(name(d.isPartnerOrders)+' · alla ordrar',all().filter(r=>r.partner===d.isPartnerOrders));}
    if(d.isHandle){const r=all().find(r=>r.id===d.isHandle);if(r){P.closeDialog();P.previewPartner(r.partner);P.go('order-list');const el=document.createElement('button');el.dataset.owOpen=r.id;document.body.append(el);el.click();el.remove();}}
    if(d.isPartner){P.selectedPartnerId=d.isPartner;partnerTab='summary';P.go('partner-detail');}
    if(d.isTab){partnerTab=d.isTab;P.render();}
    if(d.isAnalyse){f.partner=d.isAnalyse;f.channel='all';f.category='all';P.go('partner-results');}
    if(d.isEditProfile)P.partnerSetup.open(d.isEditProfile);
    if('isCost'in d)editCost();
    if('isExamples'in d&&A.admin()){const demo=all().filter(r=>r.examplePack==='flow2026'||/^order-demo-(vast|syd)-\d+$/.test(r.id));const ok=commit(m=>{for(const key of new Set(demo.filter(r=>r.status!=='draft').map(r=>r.partner+'|'+entryDate(r).slice(0,7)))){const [partner,month]=key.split('|');if(!m.costs.some(c=>c.partner===partner&&c.month===month)){const n=demo.filter(r=>r.partner===partner&&r.status!=='draft'&&entryDate(r).startsWith(month)).length;m.costs.push({partner,month,commission:n*(partner==='vast'?1250:1700),leads:n*45,campaign:n*70,other:n*39,note:'Fiktivt analysunderlag. Illustrativa kostnader, inte den avtalade provisionsberäkningen.',demo:true,at:new Date().toISOString(),actor:A.current().id});}}m.lossReasons={...m.lossReasons};demo.filter(r=>lost.has(r.status)).forEach((r,i)=>{if(!m.lossReasons[r.id])m.lossReasons[r.id]={reason:r.status==='withdrawn'?'Ånger':['Kunden avstår','Felaktiga uppgifter','Kreditbedömning'][i%3],note:'Fiktiv analysklassificering för exempelorder.',demo:true,at:new Date().toISOString(),actor:A.current().id};});});if(ok){P.render();P.toast('Fiktiva analyskompletteringar sparade. Befintligt underlag bevarat.');}else P.toast('Kunde inte spara exempelunderlaget.');}

    if('isProfile'in d){const id=selected(),old=metadata().partners?.[id]||{};editDialog('Samarbete och ansvar',field('owner','Intern ansvarig',old.owner||'')+`<label class="ow-field">Beskrivning<textarea name="description" required maxlength="3000">${e(old.description||'')}</textarea></label>`,value=>commit(m=>{m.partners={...m.partners,[id]:{...value,at:new Date().toISOString()}};}));}
    if('isModel'in d){const id=selected();editDialog('Ny versionsbeskrivning av provision',field('title','Modellnamn')+field('from','Föreslagen giltighet från',today(),'date')+'<label class="ow-field">Regler, förskott och avräkning<textarea name="description" required maxlength="4000"></textarea></label><p>Förslag för granskning. Befintlig beräkningsmotor och fakturahistorik ändras inte.</p>',value=>!valid(value.from)?'Ange giltigt datum.':commit(m=>m.models.push({...value,partner:id,id:P.newId(),at:new Date().toISOString(),actor:A.current().id})));}
    if(d.isNewUser&&A.admin()){const el=document.createElement('button');el.dataset.puNew='';document.body.append(el);el.click();el.remove();const select=document.querySelector('#pu-user-form [name="partner"]');if(select)select.value=d.isNewUser;}
    if(d.isReview){const [id,month]=d.isReview.split('|'),old=metadata().reviews?.[d.isReview]||{};if(!A.admin()){P.openDialog('Granskningsanteckning',`<p>${e(old.status||'Preliminär')}</p><p>${e(old.note||'Ingen anteckning.')}</p>`);return;}editDialog('Granska '+name(id)+' · '+month,`<label class="ow-field">Status · demo<select name="status">${options(['Preliminär','Behöver kompletteras','Granskad'].map(v=>[v,v]),old.status||'Preliminär')}</select></label><label class="ow-field">Motivering / korrigeringsbehov<textarea name="note" required maxlength="2000">${e(old.note||'')}</textarea></label><p>Belopp korrigeras i order-/kostnadsunderlaget. Granskning skickar ingen faktura.</p>`,value=>commit(m=>{m.reviews={...m.reviews,[d.isReview]:{...value,at:new Date().toISOString(),history:[...(old.history||[]),{...value,at:new Date().toISOString(),actor:A.current().id}]}};}));}
    if(d.isFinanceDetail){P.previewPartner(d.isFinanceDetail);P.go('order-commission');}
  });
  P.internalSales={filters:f,cohort,eventDate,entryDate,channel,costs,lossReason,commit,all,setSlice};
})();
